'use client';

import { useActionState, useId, useState } from 'react';
import { MAX_NOTES_LENGTH } from '@monaco/contracts';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { InventoryActionState } from '@/lib/inventory/document-form';
import { FormField } from '../../../catalogo/form-field';
import { ShortageList } from '../../document-form';

type Action = (prev: InventoryActionState, formData: FormData) => Promise<InventoryActionState>;

interface Props {
  documentId: string;
  /** The reversal's own id, generated by the page when it renders: a double confirm is one reversal. */
  reversalId: string;
  /** Names for an `INSUFFICIENT_STOCK` answer (reversing an entry whose stock was already used). */
  products: readonly { id: string; name: string; unitOfMeasure: string }[];
  action: Action;
}

/** "Revertir" with a confirmation step (D8: the whole document, once). Success redirects (the Server Action). */
export function ReverseDocument({ documentId, reversalId, products, action }: Props) {
  const uid = useId();
  const [state, formAction, pending] = useActionState<InventoryActionState, FormData>(action, {});
  const [confirming, setConfirming] = useState(false);

  const notesId = `${uid}-notes`;
  const byId = new Map(products.map((p) => [p.id, p]));
  // The hidden ids are always rendered; the confirmation (notes, errors, submit) only after "Revertir".
  return (
    <form action={formAction} className={confirming ? 'w-full space-y-3 rounded-md border p-4' : undefined} aria-label="Revertir documento">
      <input type="hidden" name="id" value={reversalId} />
      <input type="hidden" name="documentId" value={documentId} />
      {confirming ? (
        <>
          <p className="text-sm">
            ¿Revertir este documento? Se registrará un documento de reversión con los movimientos opuestos en cada punto de venta. Un documento solo se puede
            revertir una vez y la reversión no se puede deshacer.
          </p>
          <FormField id={notesId} label="Notas (opcional)">
            <Input id={notesId} name="notes" maxLength={MAX_NOTES_LENGTH} />
          </FormField>
          {state.error ? (
            <div role="alert" className="rounded-md border border-red-300 bg-red-50 p-3 text-sm text-red-700">
              <p>{state.error}</p>
              {state.shortages?.length ? <ShortageList shortages={state.shortages} products={byId} /> : null}
            </div>
          ) : null}
          <div className="flex gap-2">
            <Button type="submit" variant="destructive" disabled={pending}>
              {pending ? 'Revirtiendo…' : 'Confirmar reversión'}
            </Button>
            <Button type="button" variant="outline" disabled={pending} onClick={() => setConfirming(false)}>
              Cancelar
            </Button>
          </div>
        </>
      ) : (
        <Button type="button" variant="outline" onClick={() => setConfirming(true)}>
          Revertir
        </Button>
      )}
    </form>
  );
}
